// frameState walks g.rolls and returns:
//   frame: 1-based frame number of the next roll
//   pinsInFrame: pins knocked down in the current (in-progress) frame since the last reset
//   rollsInFrame: rolls taken in the current frame
//   complete: whether all 10 frames are finished
func (g *Game) frameState() (frame, pinsInFrame, rollsInFrame int, complete bool) {
	frame = 1
	for len(g.rolls) > 0 {
		first := g.rolls[0]
		if first == 10 {
			g.rolls = g.rolls[1:]
			pinsInFrame = 0
			rollsInFrame = 0
			// strike completes the frame in frames 1-9
			if frame < 10 {
				frame++
			}
			// in frame 10, the strike does not complete the frame
		} else if len(g.rolls) > 1 {
			second := g.rolls[1]
			g.rolls = g.rolls[2:]
			if first+second == 10 {
				pinsInFrame = 0
				rollsInFrame = 0
				if frame < 10 {
					frame++
				}
			} else {
				pinsInFrame = first + second
				rollsInFrame = 2
				if frame == 10 {
					complete = true
				} else {
					frame++
					pinsInFrame = 0
					rollsInFrame = 0
				}
			}
		} else {
			// single roll in progress
			pinsInFrame = first
			rollsInFrame = 1
			g.rolls = nil
		}
		if complete {
			break
		}
	}
	return
}
