		if len(rolls) > 0 {
			pinsInFrame = rolls[0]
		}
		return
	}

	// Tenth frame: a strike or a spare earns one or two fill balls.
	if rolls[0] == 10 {
		rolls = rolls[1:]
		pinsInFrame = 0
		fills := 0
		for len(rolls) > 0 && fills < 2 {
			fills++
			if rolls[0] == 10 {
				rolls = rolls[1:]
				pinsInFrame = 0
			} else {
				pinsInFrame = rolls[0]
				rolls = nil
			}
		}
		complete = fills == 2
		return
